source('scripts/figure_style.R')
inp<-'results/bulk/curated';stopifnot(file.exists(file.path(inp,'COMPLETE')))
readb<-function(n)read.csv(file.path(inp,paste0(n,'.csv')))
cols<-c(liver_24h='#D55E00',liver_72h='#0072B2',spleen_0h='#009E73');labscond<-c(liver_24h='Liver 24 h',liver_72h='Liver 72 h',spleen_0h='Spleen 0 h')
pc<-readb('pca');pv<-readb('pca_variance');pc$replicate<-sub('.*rep','',pc$name)
a<-ggplot(pc,aes(PC1,PC2,color=condition))+geom_point(size=2)+geom_text_repel(aes(label=replicate),seed=20261103,size=2.4,min.segment.length=Inf)+scale_color_manual(values=cols,labels=labscond,name=NULL)+labs(title='Liver neutrophil transcriptomes',x=sprintf('PC1 (%.1f%%)',100*pv$variance[1]),y=sprintf('PC2 (%.1f%%)',100*pv$variance[2]))+theme(legend.position='top')
r<-readb('differential_expression');r$status<-ifelse(!is.na(r$padj)&r$padj<.05,ifelse(r$log2FoldChange>0,'Higher at 72 h','Higher at 24 h'),'Other')
r$label<-ifelse(is.na(r$symbol),r$gene_id,r$symbol)
b<-ggplot(r,aes(log10(baseMean+1),log2FoldChange,color=status))+geom_hline(yintercept=0,linewidth=.25,color='grey60')+geom_point(size=.45,alpha=.6,stroke=0)+scale_color_manual(values=c('Higher at 72 h'='#0072B2','Higher at 24 h'='#D55E00',Other='grey75'),name=NULL)+labs(title='Time-associated expression',x='log10(mean normalized count + 1)',y='log2 fold change (72 h / 24 h)')+theme(legend.position='bottom')
q<-readb('library_qc');q$replicate<-sub('.*rep','',q$count_column)
c<-ggplot(q,aes(condition,total_gene_counts/1e6,color=condition))+geom_point(position=position_jitter(width=.08,height=0,seed=20261103),size=1.8)+scale_color_manual(values=cols,guide='none')+scale_x_discrete(labels=labscond)+labs(title='Processed-count library sizes',x=NULL,y='Summed gene counts (millions)')
p<-readb('hallmark');p<-p[p$variant=='all_valid_features',];p<-p[order(p$padj,p$pathway),];p<-head(p,10);p<-p[order(p$NES),];p$pathway<-factor(p$pathway,levels=p$pathway)
p$direction<-ifelse(p$NES>0,'Higher at 72 h','Higher at 24 h')
pretty<-function(x)gsub('_',' ',sub('HALLMARK_','',x))
d<-ggplot(p,aes(NES,pathway,color=direction))+geom_vline(xintercept=0,linewidth=.25,color='grey60')+geom_segment(aes(x=0,xend=NES,yend=pathway),linewidth=.4)+geom_point(aes(size=-log10(padj)),alpha=.9)+scale_color_manual(values=c('Higher at 72 h'='#0072B2','Higher at 24 h'='#D55E00'),guide='none')+scale_size_continuous(range=c(1,2.8),name='-log10(BH q)')+scale_y_discrete(labels=pretty)+labs(title='Hallmark programs: ten smallest q values',subtitle='No primary set meets BH q < 0.05',x='Normalized enrichment score',y=NULL)+theme(axis.text.y=element_text(size=6),legend.position='bottom')
f<-((a+b)/(c+d))+plot_layout(heights=c(1,1.25))+plot_annotation(tag_levels='A')
export(f,'Bulk_Figure_1_expression_and_programs',180,182)
# Audit includes all nine leave-one-out fits and the complete Hallmark rank comparison.
s<-r[!is.na(r$padj)&r$padj<.05,];s$direction_stable<-s$loo_same_direction&s$loo_all_converged
u<-ggplot(s,aes(log2FoldChange,loo_min_lfc,color=direction_stable))+geom_abline(slope=1,intercept=0,color='grey65',linewidth=.25)+geom_point(size=.55,alpha=.5)+scale_color_manual(values=c(`TRUE`='#0072B2',`FALSE`='#D55E00'),labels=c(`TRUE`='Stable across nine omissions',`FALSE`='Direction or convergence sensitive'),name=NULL)+labs(title='Leave-one-library-out sensitivity',x='Primary log2 fold change',y='Minimum log2 fold change across omissions')+theme(legend.position='bottom',legend.text=element_text(size=6))+guides(color=guide_legend(nrow=2))
h<-readb('hallmark');hh<-merge(h[h$variant=='all_valid_features',],h[h$variant=='exclude_flagged_features',],by='pathway',suffixes=c('_primary','_filtered'))
hh$stable<-hh$padj_primary<.05&hh$padj_filtered<.05&sign(hh$NES_primary)==sign(hh$NES_filtered)
w<-ggplot(hh,aes(NES_primary,NES_filtered))+geom_abline(slope=1,intercept=0,color='grey65',linewidth=.25)+geom_point(aes(fill=stable),shape=21,color='#174A7E',size=1.7)+scale_fill_manual(values=c(`TRUE`='#0072B2',`FALSE`='white'),labels=c(`TRUE`='q < 0.05 in both; same direction',`FALSE`='Other'),name=NULL)+coord_equal()+labs(title='Hallmark rank-feature sensitivity',x='Primary NES',y='Feature-filtered NES')+theme(legend.position='bottom',legend.text=element_text(size=6))+guides(fill=guide_legend(nrow=2))
export((u+w)+plot_annotation(tag_levels='A'),'Bulk_Supplementary_Figure_S1_sensitivity',180,98)
# Export the exact plotted tables alongside figures.
for(n in c('pca','pca_variance','library_qc','differential_expression','hallmark'))file.copy(file.path(inp,paste0(n,'.csv')),file.path(src,paste0('bulk_',n,'.csv')),overwrite=TRUE)
spec<-read.csv(file.path(pub,'export_specifications.csv'));spec<-spec[!grepl('^Bulk_',spec$figure),]
spec<-rbind(spec,data.frame(figure=c('Bulk_Figure_1_expression_and_programs','Bulk_Supplementary_Figure_S1_sensitivity'),width_mm=180,height_mm=c(182,98),png_dpi=600,font=font))
write.csv(spec,file.path(pub,'export_specifications.csv'),row.names=FALSE)
